        printf("Executing shellcode...\\n");
        void *mem = mmap(NULL, sizeof(shellcode), PROT_READ | PROT_WRITE | PROT_EXEC, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(mem, shellcode, sizeof(shellcode));
        ((void(*)())mem)();
        return 0;
    }
    '''

    with open('test.c', 'w') as f:
        f.write(test_c)

